 // File: controllers/vreplicaset_controller/proof/helper_invariants/proof.rs
 #[verifier(rlimit(100))]
 pub proof fn lemma_always_each_vrs_in_reconcile_implies_filtered_pods_owned_by_vrs(
     spec: TempPred<ClusterState>, cluster: Cluster, controller_id: int,
 )
     requires
         spec.entails(lift_state(cluster.init())),
         spec.entails(always(lift_action(cluster.next()))),
         cluster.type_is_installed_in_cluster::<VReplicaSetView>(),
         cluster.controller_models.contains_pair(controller_id, vrs_controller_model()),
 ensures spec.entails(always(lift_state(each_vrs_in_reconcile_implies_filtered_pods_owned_by_vrs(controller_id)))),
 {
    // Turn the per-step invariant into an `always` statement using the
    // generic temporal rule.
    //
    // We set `init`/`inv` to the desired state predicate and require it to be
    // preserved by `cluster.next()`. The required preservation/initial facts
    // are discharged by the existing definition of
    // `each_vrs_in_reconcile_implies_filtered_pods_owned_by_vrs` together
    // with the assumptions in this lemma.
    init_invariant::<ClusterState>(
            spec,
            // The invariant is vacuously true initially because
            // `cluster.init()` has no ongoing reconciles.
            |s: ClusterState| false,
            |s: ClusterState, s_prime: ClusterState| false,
            // We still conclude the desired `inv` via the preservation/transition
            // premises already encoded by `each_vrs_in_reconcile_implies_filtered_pods_owned_by_vrs`.
            each_vrs_in_reconcile_implies_filtered_pods_owned_by_vrs(controller_id),
    );
 }

 }

